create table app_users(id bigint generated by default as identity primary key,name varchar(255) not null,email varchar(255) not null unique,password_hash varchar(255),role varchar(255) not null,google_subject varchar(255) unique);
create table wallets(id bigint generated by default as identity primary key,user_id bigint not null unique references app_users(id),balance numeric(14,2) not null);
create table categories(id bigint generated by default as identity primary key,user_id bigint not null references app_users(id),name varchar(255) not null,icon varchar(255) not null,system_defined boolean not null,unique(user_id,name));
create table budgets(id bigint generated by default as identity primary key,user_id bigint not null references app_users(id),category_id bigint not null references categories(id),monthly_limit numeric(14,2) not null,warning_percent integer not null);
create table expense_transactions(id bigint generated by default as identity primary key,user_id bigint not null references app_users(id),merchant_name varchar(255) not null,description varchar(500),amount numeric(14,2) not null,category_id bigint not null references categories(id),ai_suggested_category varchar(255) not null,ai_confidence float(53) not null,status varchar(255) not null,occurred_at timestamp not null);

